1	"use client";
2	
3	import { useState } from "react";
4	import Link from "next/link";
5	import { orderHostingAccount, retryHostingProvision, type HostingAccountView } from "@/lib/actions-hosting";
6	import { Badge, EmptyState, StatusDot, fmtMoney } from "@/components/ui/primitives";
7	import { recommendHostingPlan } from "@/lib/hosting/recommend";
8	import { ANNUAL_TERM_MONTHS, DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
9	import { TermLadder } from "@/components/customer/TermLadder";
10	
11	type PlanView = {
12	  id: string;
13	  name: string;
14	  priceCents: number;
15	  diskGB: number;
16	  maxSites: number;
17	  maxDatabases: number;
18	  bandwidthTB: number;
19	  mailboxes: number;
20	  freeMigration: boolean;
21	  featured: boolean;
22	  tagline: string;
23	};
24	
25	export function HostingClient({
26	  plans,
27	  accounts,
28	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
29	  firstMonthFree = false,
30	}: {
31	  plans: PlanView[];
32	  accounts: HostingAccountView[];
33	  /** Live admin annual discount (%), so the Annual term shows the REAL price/savings. */
34	  annualDiscountPct?: number;
35	  /**
36	   * Is the first-month-free promo live for shared hosting? Resolved server-side
37	   * (firstMonthFreeAppliesTo("HOSTING") + owner toggle) so the "FREE first month"
38	   * copy shows ONLY when checkout will actually grant it. Display only — the charge
39	   * logic lives in orderHostingAccount; nothing here alters what is billed.
40	   */
41	  firstMonthFree?: boolean;
42	}) {
43	  const [domain, setDomain] = useState("");
44	  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
45	  // Default to the ANNUAL term — the recommended, better-value choice. Monthly
46	  // stays one click away in the ladder below. termPriceCents (server-side) charges
47	  // exactly what the ladder shows, so this is a nudge, never a hidden cost.
48	  const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
49	  const [busy, setBusy] = useState(false);
50	  const [error, setError] = useState("");
51	  const [ok, setOk] = useState("");
52	
53	  const selectedPlan = plans.find((p) => p.id === planId) ?? null;
54	
55	  async function order() {
56	    if (!planId || !domain.trim()) return;
57	    setBusy(true);
58	    setError("");
59	    setOk("");
60	    try {
61	      const res = await orderHostingAccount(planId, domain.trim(), termMonths);
62	      if (res.error) setError(res.error);
63	      else {
64	        setOk("Account created — it’s being set up now.");
65	        setDomain("");
66	        setTimeout(() => window.location.reload(), 900);
67	      }
68	    } catch {
69	      setError("Something went wrong. Your wallet was not charged — try again.");
70	    } finally {
71	      setBusy(false);
72	    }
73	  }
74	
75	  async function retry(id: string) {
76	    setError("");
77	    // Previously the result was discarded and the page reloaded unconditionally,
78	    // so a rejected retry (e.g. "isn't in a failed state") vanished. Surface it —
79	    // the order path above already does the same.
80	    const res = await retryHostingProvision(id);
81	    if (res.error) {
82	      setError(res.error);
83	      return;
84	    }
85	    window.location.reload();
86	  }
87	
88	  return (
89	    <div className="space-y-8">
90	      <div>
91	        <h1 className="text-xl font-semibold">Web Hosting</h1>
92	        <p className="mt-1 text-sm text-slate-400">
93	          Host your website without managing a server — we run PHP, databases, email and SSL for you. Point your
94	          domain at us and you’re live.
95	        </p>
96	      </div>
97	
98	      {/* Your accounts — compact cards linking to the per-account dashboard. */}
99	      {accounts.length > 0 ? (
100	        <div className="space-y-4">
101	          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">Your hosting accounts</h2>
102	          <div className="grid gap-3 sm:grid-cols-2">
103	            {accounts.map((a) => (
104	              <AccountCard key={a.id} a={a} onRetry={() => retry(a.id)} />
105	            ))}
106	          </div>
107	        </div>
108	      ) : (
109	        <EmptyState
110	          title="No hosting accounts yet"
111	          sub="Pick a plan below, enter your domain, and we’ll set up an isolated hosting account for you in a minute."
112	        />
113	      )}
114	
115	      {/* Order a (new) site. */}
116	      <div className="card">
117	        <h2 className="mb-1 font-semibold">{accounts.length ? "Host another site" : "Host a new site"}</h2>
118	        <p className="mb-3 text-xs text-slate-500">Each site gets its own isolated account, storage quota and databases.</p>
119	        {firstMonthFree && plans.length > 0 && (
120	          <div className="mb-3 flex items-center gap-2 rounded-xl border border-emerald-500/25 bg-emerald-500/10 px-3 py-2 text-sm font-medium text-emerald-300">
121	            <span className="flex h-1.5 w-1.5 shrink-0 rounded-full bg-emerald-400 animate-pulse-dot" />
122	            Your first month is free on shared hosting — then the price you sign up at is the price you renew at.
123	          </div>
124	        )}
125	        {error && <div className="mb-3 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}
126	        {ok && <div className="mb-3 rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">{ok}</div>}
127	        {plans.length === 0 ? (
128	          <p className="text-sm text-slate-400">No hosting plans are available yet. Check back soon.</p>
129	        ) : (
130	          <>
131	            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
132	              {plans.map((p) => {
133	                const rec = recommendHostingPlan(p);
134	                const selected = planId === p.id;
135	                return (
136	                  <button
137	                    key={p.id}
138	                    type="button"
139	                    onClick={() => setPlanId(p.id)}
140	                    className={`relative flex flex-col rounded-xl border px-4 py-3 text-left transition ${
141	                      selected ? "border-brand-400 bg-brand-500/10" : p.featured ? "border-brand-500/40 hover:border-brand-400" : "border-white/10 hover:border-white/20"
142	                    }`}
143	                  >
144	                    {p.featured && (
145	                      <span className="absolute -top-2 right-3 rounded-full bg-brand-500 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-white">
146	                        Most popular
147	                      </span>
148	                    )}
149	                    <div className="flex items-baseline justify-between gap-2">
150	                      <span className="font-medium">{p.name}</span>
151	                      {firstMonthFree ? (
152	                        <span className="text-right leading-tight">
153	                          <span className="block text-xs font-bold uppercase tracking-wide text-emerald-300">Free first month</span>
154	                          <span className="block text-[11px] text-slate-500">
155	                            renews at {fmtMoney(p.priceCents)}/mo
156	                          </span>
157	                        </span>
158	                      ) : (
159	                        <span className="text-sm font-semibold">
160	                          {fmtMoney(p.priceCents)}
161	                          <span className="text-xs text-slate-500">/mo</span>
162	                        </span>
163	                      )}
164	                    </div>
165	                    <p className="mt-1.5 text-xs font-medium text-brand-200">{p.tagline || rec.headline}</p>
166	                    <ul className="mt-2 space-y-0.5 text-xs text-slate-400">
167	                      <li>{p.diskGB} GB NVMe SSD storage</li>
168	                      <li>{p.maxSites} website{p.maxSites === 1 ? "" : "s"}</li>
169	                      <li>{p.maxDatabases} database{p.maxDatabases === 1 ? "" : "s"}</li>
170	                      <li>{p.bandwidthTB} TB bandwidth</li>
171	                      <li>{p.mailboxes} email mailbox{p.mailboxes === 1 ? "" : "es"} · free SSL</li>
172	                      {p.freeMigration && <li className="text-emerald-300/90">✓ Free website migration</li>}
173	                    </ul>
174	                    <p className="mt-2 text-[11px] leading-snug text-slate-500">{rec.detail}</p>
175	                  </button>
176	                );
177	              })}
178	            </div>
179	            {selectedPlan && (
180	              <div className="mt-4">
181	                <div className="mb-1.5 flex items-baseline justify-between gap-2">
182	                  <label className="label mb-0">Billing term</label>
183	                  <span className="text-[11px] text-slate-500">Commit longer, pay less per month</span>
184	                </div>
185	                <TermLadder
186	                  monthlyCents={selectedPlan.priceCents}
187	                  annualDiscountPct={annualDiscountPct}
188	                  value={termMonths}
189	                  onChange={setTermMonths}
190	                />
191	              </div>
192	            )}
193	            <div className="mt-4 flex flex-wrap items-end gap-3">
194	              <div className="min-w-[220px] flex-1">
195	                <label className="label">Your domain</label>
196	                <input className="input" placeholder="example.com" value={domain} onChange={(e) => setDomain(e.target.value)} />
197	              </div>
198	              <button className="btn-primary" disabled={busy || !planId || !domain.trim()} onClick={order}>
199	                {busy ? "Creating…" : "Create account"}
200	              </button>
201	            </div>
202	            {firstMonthFree && selectedPlan && (
203	              <p className="mt-2 text-xs text-emerald-300/90">
204	                <span className="font-semibold">Free first month</span> — $0 today, then {selectedPlan.name} renews at{" "}
205	                {fmtMoney(selectedPlan.priceCents)}/mo. No teaser jump: the price you sign up at is the price you renew at.
206	              </p>
207	            )}
208	            <p className="mt-2 text-xs text-slate-500">
209	              Charged from your wallet. You don’t need to move your domain yet — you’ll get the exact DNS record to set
210	              after it’s created.
211	            </p>
212	          </>
213	        )}
214	      </div>
215	    </div>
216	  );
217	}
218	
219	/* ---------------------------------------------------------------- card --- */
220	
221	function AccountCard({ a, onRetry }: { a: HostingAccountView; onRetry: () => void }) {
222	  const diskGB = Math.round(a.diskQuotaMB / 1024);
223	  const storage = a.diskUsedMB != null ? `${(a.diskUsedMB / 1024).toFixed(a.diskUsedMB < 1024 ? 2 : 1)} / ${diskGB} GB` : `${diskGB} GB`;
224	
225	  const body = (
226	    <>
227	      <div className="flex items-start justify-between gap-2">
228	        <div className="min-w-0">
229	          <p className="truncate font-medium text-slate-100">{a.primaryDomain}</p>
230	          <p className="mt-0.5 text-xs text-slate-500">{a.planName} · PHP {a.phpVersion}</p>
231	        </div>
232	        <StatusDot status={a.status} />
233	      </div>
234	      <div className="mt-3 flex flex-wrap items-center gap-2 text-[11px] text-slate-400">
235	        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">Storage {storage}</span>
236	        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">{a.maxSites} extra site{a.maxSites === 1 ? "" : "s"}</span>
237	        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">{a.maxDatabases} DB{a.maxDatabases === 1 ? "" : "s"}</span>
238	        {a.sslActive && <Badge tone="green">HTTPS</Badge>}
239	      </div>
240	    </>
241	  );
242	
243	  // A failed account can't be opened usefully — show the retry affordance inline.
244	  if (a.status === "FAILED") {
245	    return (
246	      <div className="card">
247	        {body}
248	        <div className="mt-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-300">
249	          Setup failed{a.error ? `: ${a.error}` : ""}.{" "}
250	          <button className="font-medium underline" onClick={onRetry}>Retry setup</button>
251	        </div>
252	      </div>
253	    );
254	  }
255	
256	  return (
257	    <Link href={`/dashboard/hosting/${a.id}`} className="card card-hover block transition">
258	      {body}
259	      <p className="mt-3 text-xs font-medium text-brand-300">Manage →</p>
260	    </Link>
261	  );
262	}
