1	"use server";
2	
3	import { randomBytes } from "node:crypto";
4	import { Prisma } from "@prisma/client";
5	import { revalidatePath } from "next/cache";
6	import { cookies, headers } from "next/headers";
7	import { db } from "./db";
8	import { requireUser, assertNotImpersonating } from "./auth";
9	import { requireArea } from "./rbac";
10	import { debitWallet, InsufficientBalanceError } from "./wallet";
11	import { nodeThresholds, hostingNodeUtil, severityFor } from "./node-capacity";
12	import { SANDBOX } from "./sandbox";
13	import { addMonths, normalizeProductTerm, termPriceCents, vpsTerm } from "./billing-terms";
14	import { annualDiscountPct } from "./annual-discount";
15	import { clientIp } from "./rate-limit";
16	import { hashIp } from "./coupon-order";
17	import {
18	  claimFirstMonthFree,
19	  firstMonthCreditCents,
20	  firstMonthFreeEnabled,
21	  firstMonthFreeAppliesTo,
22	  firstMonthFreeEligible,
23	  promoCampaignFromCookie,
24	  setPromoOrderRef,
25	} from "./promo-redemption";
26	import { emailVerificationError } from "./email-verification";
27	import { encryptSecret, decryptSecret } from "./crypto-box";
28	import {
29	  isValidHostingDomain,
30	  normalizeHostingDomain,
31	  normalizeClaimHostname,
32	  deriveUsername,
33	  isValidUnixUsername,
34	  isValidSubdomainLabel,
35	  isValidCronSchedule,
36	  isValidCronCommand,
37	  subdomainPaths,
38	  addonDomainPaths,
39	  planLimits,
40	  pointToRecords,
41	  isValidDbToolToken,
42	} from "./hosting";
43	import { hostingAppCatalog } from "../worker/hosting";
44	import { fsList, fsMkdir, fsDelete, fsTargetFor, type HostingFsTarget } from "./hosting-fs";
45	
46	export type HostingResult = { ok?: boolean; error?: string; accountId?: string };
47	
48	// The active-ish states that reserve a domain / occupy a node slot.
49	const LIVE_STATES = ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] as const;
50	
51	/** Least-loaded enabled+online node with account headroom. */
52	async function scheduleHostingNode(): Promise<{ id: string } | null> {
53	  const nodes = await db.hostingNode.findMany({ where: { enabled: true, status: "ONLINE" } });
54	  if (!nodes.length) return null;
55	  const loads = await Promise.all(
56	    nodes.map(async (n) => ({
57	      node: n,
58	      used: await db.hostingAccount.count({ where: { hostingNodeId: n.id, status: { in: [...LIVE_STATES] } } }),
59	    })),
60	  );
61	  const withRoom = loads.filter((l) => l.used < l.node.maxAccounts).sort((a, b) => a.used - b.used);
62	  return withRoom.length ? { id: withRoom[0].node.id } : null;
63	}
64	
65	/** A free jailed username on the node, derived from the email + random salt. */
66	async function pickUsername(nodeId: string, emailSeed: string): Promise<string> {
67	  for (let i = 0; i < 8; i++) {
68	    const name = deriveUsername(emailSeed, randomBytes(4).toString("hex"));
69	    if (!isValidUnixUsername(name)) continue;
70	    const taken = await db.hostingAccount.findUnique({ where: { hostingNodeId_username: { hostingNodeId: nodeId, username: name } } });
71	    if (!taken) return name;
72	  }
73	  throw new Error("Could not allocate a username — try again.");
74	}
75	
76	/**
77	 * Order a shared-hosting account for a domain on a plan. Same purchase discipline
78	 * as every other paid path: no spending while impersonating, verified email,
79	 * wallet charge in the same tx that creates the record. The account starts
80	 * PENDING; the worker provisioner brings it up (inert until shared hosting is
81	 * enabled — see worker/hosting.ts).
82	 */
83	export async function orderHostingAccount(
84	  planId: string,
85	  domain: string,
86	  termMonthsRaw?: number,
87	): Promise<HostingResult> {
88	  const user = await requireUser();
89	  await assertNotImpersonating();
90	  const unverified = await emailVerificationError(user);
91	  if (unverified) return { error: unverified };
92	
93	  const name = normalizeHostingDomain(domain);
94	  if (!name) return { error: "Enter a domain." };
95	  if (!isValidHostingDomain(name)) return { error: "Enter a valid domain (e.g. example.com)." };
96	
97	  const plan = await db.hostingPlan.findUnique({ where: { id: planId } });
98	  if (!plan || !plan.active) return { error: "That hosting plan isn’t available." };
99	
100	  // One account per domain across ALL customers — same cross-tenant guard as
101	  // email subscriptions (a shared vhost keys on server_name).
102	  const dupe = await db.hostingAccount.findFirst({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } });
103	  if (dupe) {
104	    return {
105	      error:
106	        dupe.userId === user.id
107	          ? "You already have a hosting account for this domain."
108	          : "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across.",
109	    };
110	  }
111	  // Also reject if this hostname is already someone's subdomain or addon domain
112	  // (audit HIGH-2: the primary-order guard used to ignore those two tables).
113	  if (await isHostnameClaimed(name)) {
114	    return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
115	  }
116	
117	  const node = await scheduleHostingNode();
118	  if (!node) return { error: "No shared-hosting capacity is available right now — please try again shortly." };
119	
120	  // Managed first-month-free. `promoCharge` is $0 (a single-month hosting term is
121	  // free); `fullCharge` is the plan price. The credit is granted ONLY if the atomic
122	  // claim inside the charge tx succeeds — otherwise (already redeemed by this
123	  // account/IP, or the promo is off) the account is created at FULL price. We
124	  // pre-check eligibility only to pick the balance gate: a first-time customer with
125	  // a $0 balance can still sign up free, a repeat one is gated against full price.
126	  // First-month-free is scoped to Shared Web Hosting (this flow) — the one
127	  // product the promo applies to. See firstMonthFreeAppliesTo.
128	  const promoEnabled = firstMonthFreeAppliesTo("HOSTING") && (await firstMonthFreeEnabled());
129	  const campaign = promoCampaignFromCookie(await cookies());
130	  const ipHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
131	  // Billing term (Monthly / Annual). The annual rate is the admin setting, resolved
132	  // ONCE here, frozen onto the account, charged up front and read back at renewal —
133	  // so displayed === charged === renewed. A malformed term falls back to monthly.
134	  const term = normalizeProductTerm(termMonthsRaw);
135	  const annualPct = await annualDiscountPct();
136	  const fullCharge = termPriceCents(plan.priceCents, term, annualPct);
137	  // First-month-free must credit EXACTLY ONE MONTH — never zero a whole annual term.
138	  // `firstMonthCreditCents(fullCharge, term)` returns the full charge for a 1-month
139	  // term (genuinely free first month, $0) and one month's share for the annual term,
140	  // so annual + promo = "one month credited, the other 11 months charged".
141	  const promoCharge = Math.max(0, fullCharge - firstMonthCreditCents(fullCharge, term));
142	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
143	  const anticipated = eligible ? promoCharge : fullCharge;
144	  if (user.balanceCents < anticipated) return { error: "Insufficient balance. Top up your wallet first." };
145	
146	  const limits = planLimits(plan);
147	  const username = await pickUsername(node.id, user.email.split("@")[0] ?? "acct");
148	
149	  let accountId = "";
150	  try {
151	    await db.$transaction(async (tx) => {
152	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
153	      let debitCents = fullCharge;
154	      let promoClaimId: string | null = null;
155	      if (promoEnabled) {
156	        const claim = await claimFirstMonthFree(tx, {
157	          userId: user.id,
158	          ipHash,
159	          serviceType: "HOSTING",
160	          campaign,
161	          chargedCents: promoCharge,
162	        });
163	        if (claim.claimed) {
164	          debitCents = promoCharge;
165	          promoClaimId = claim.id;
166	        }
167	      }
168	      const note = debitCents < fullCharge ? " — First month free" : "";
169	      // Term shown on the ledger line: an annual account reads "Annual ($X.XX/mo)"
170	      // so the customer sees the yearly commitment AND its real per-month rate.
171	      const effMonthly = term > 1 ? Math.round(fullCharge / term) : 0;
172	      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
173	      await debitWallet(tx, user.id, debitCents);
174	      await tx.walletTransaction.create({
175	        data: { userId: user.id, amountCents: -debitCents, description: `Web Hosting: ${plan.name} for ${name} — ${termLabel}${note}` },
176	      });
177	      const acct = await tx.hostingAccount.create({
178	        // Cast: the symlinked prod Prisma client's types predate `termMonths` /
179	        // `annualDiscountPct` on HostingAccount until it is regenerated at deploy
180	        // (identical at runtime then — see lib/order.ts's Server create).
181	        data: {
182	          userId: user.id,
183	          hostingNodeId: node.id,
184	          planId: plan.id,
185	          username,
186	          primaryDomain: name,
187	          status: "PENDING",
188	          diskQuotaMB: limits.diskGB * 1024,
189	          maxSites: limits.maxSites,
190	          maxDatabases: limits.maxDatabases,
191	          // The term this account was SOLD on, and the annual rate frozen at sale, so
192	          // the renewal sweep bills the SAME price it was ordered at (worker/product-renewals.ts).
193	          termMonths: term,
194	          annualDiscountPct: annualPct,
195	          expiresAt: addMonths(new Date(), term),
196	        } as Prisma.HostingAccountUncheckedCreateInput,
197	      });
198	      accountId = acct.id;
199	      // Atomic hostname claim in the SAME tx as the account row. A colliding
200	      // primaryDomain (another order, or someone's subdomain/addon of the same
201	      // name racing us past the advisory isHostnameClaimed check) fails here on
202	      // UNIQUE(hostname) → the whole tx (incl. the wallet debit) rolls back.
203	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(name), accountId: acct.id, kind: "PRIMARY" } });
204	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, acct.id, debitCents);
205	    });
206	  } catch (e) {
207	    if (isUniqueViolation(e)) {
208	      return { error: "That domain is already hosted on Nxeon. If it’s yours, contact support to move it across." };
209	    }
210	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
211	  }
212	
213	  await db.auditLog.create({ data: { userId: user.id, action: "hosting.order", detail: `${plan.name} · ${name}` } }).catch(() => {});
214	  revalidatePath("/dashboard/hosting");
215	  return { ok: true, accountId };
216	}
217	
218	export type HostingAccountView = {
219	  id: string;
220	  primaryDomain: string;
221	  planName: string;
222	  status: string;
223	  username: string;
224	  pointToA: string;
225	  pointToCname: string | null;
226	  diskQuotaMB: number;
