423	export async function listHostingTasks(accountId: string): Promise<{ id: string; kind: string; status: string; result: string | null; error: string | null; createdAt: string }[]> {
424	  const user = await requireUser();
425	  // A DONE task result can carry a one-time secret (the WordPress admin password);
426	  // an impersonating admin must not read it out (audit LOW-1, same as reveal above).
