699	/**
700	 * Is this hostname already claimed ANYWHERE? A shared node routes purely by nginx
701	 * `server_name`, and a hostname can live in THREE places — a primary domain, a
702	 * subdomain, or an addon domain. Before this, each creator only checked its own
703	 * table, so an addon could shadow a victim's subdomain (or vice-versa) on a
704	 * co-located node = cross-tenant vhost takeover (security audit HIGH-1/HIGH-2).
705	 *
706	 * This is now a FAST, FRIENDLY PRE-CHECK only — good UX (an early, clear error)
707	 * but NOT trusted alone: a non-atomic read can't stop two concurrent requests
708	 * from both passing it and both committing the same server_name (the co-tenant
709	 * vhost-shadowing TOCTOU). The authoritative guard is the atomic UNIQUE(hostname)
710	 * insert into HostingHostnameClaim done INSIDE each creator's transaction — a
711	 * colliding claim fails there (P2002) and rolls the whole tx back.
712	 */
713	async function isHostnameClaimed(name: string): Promise<boolean> {
714	  // The authoritative registry (single UNIQUE(hostname) spanning all three kinds)
715	  // is the fast, definitive pre-check now. We also still scan the three resource
716	  // tables so any legacy row created before the claims table existed is honoured.
717	  const host = normalizeClaimHostname(name);
718	  const [claim, prim, sub, addon] = await Promise.all([
719	    db.hostingHostnameClaim.count({ where: { hostname: host } }),
720	    db.hostingAccount.count({ where: { primaryDomain: name, status: { in: [...LIVE_STATES] } } }),
721	    db.hostingSubdomain.count({ where: { fqdn: name, status: { in: [...SITE_STATES] } } }),
722	    db.hostingAddonDomain.count({ where: { domain: name, status: { in: [...SITE_STATES] } } }),
723	  ]);
724	  return claim + prim + sub + addon > 0;
725	}
