769	export async function createSubdomain(accountId: string, label: string): Promise<HostingResult> {
770	  const ctx = await ownedSiteAccount(accountId);
771	  if ("error" in ctx) return { error: ctx.error };
772	  const { a } = ctx;
773	  const clean = String(label ?? "").trim().toLowerCase();
774	  if (!isValidSubdomainLabel(clean)) return { error: "Enter a valid subdomain label — letters, digits and hyphens only." };
775	  const fqdn = `${clean}.${a.primaryDomain}`;
776	  if (!isValidHostingDomain(fqdn)) return { error: "That subdomain isn’t a valid hostname." };
777	  // Reject if another tenant already claimed this exact hostname as an addon domain
778	  // (or primary). fqdn @unique blocks subdomain↔subdomain; this closes the addon
779	  // path (audit HIGH-1, reverse direction).
780	  if (await isHostnameClaimed(fqdn)) {
781	    return { error: "That hostname is already in use on Nxeon." };
782	  }
783	  const { docroot } = subdomainPaths(a.username, clean);
784	  try {
785	    await db.$transaction(async (tx) => {
786	      const subs = await tx.hostingSubdomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
787	      const addons = await tx.hostingAddonDomain.count({ where: { accountId: a.id, status: { in: [...SITE_STATES] } } });
788	      if (subs + addons >= a.maxSites) throw new Error("CAP");
789	      const sub = await tx.hostingSubdomain.create({ data: { accountId: a.id, label: clean, fqdn, docroot, status: "PENDING" } });
790	      // Atomic cross-tenant claim in the SAME tx: the UNIQUE(hostname) — not the
791	      // advisory isHostnameClaimed read above — is what actually stops a co-tenant
792	      // from committing this same server_name as their primary/subdomain/addon.
793	      await tx.hostingHostnameClaim.create({ data: { hostname: normalizeClaimHostname(fqdn), accountId: a.id, kind: "SUBDOMAIN" } });
794	      await tx.hostingTask.create({ data: { accountId: a.id, kind: "CREATE_SUBDOMAIN", payload: JSON.stringify({ subdomainId: sub.id }) } });
795	    }, { isolationLevel: "Serializable" });
796	  } catch (e) {
797	    if (e instanceof Error && e.message === "CAP") return { error: siteCapMessage(a.maxSites) };
798	    if (isUniqueViolation(e)) return { error: "That hostname is already in use on Nxeon." };
799	    return { error: "That subdomain already exists, or the request raced — try again." };
800	  }
801	  revalidatePath(`/dashboard/hosting/${accountId}`);
802	  return { ok: true };
803	}
