126	  /** Promo rate (%) that produced it; persisted as `Server.termPromoPercent`. */
127	  promoPercent: number;
128	  /** Promo name for the ledger / invoice line, e.g. "Summer Sale". */
129	  promoName: string;
130	  /**
131	   * VAT/GST on the net (Finding 1), carried through the card round-trip so the
132	   * confirm route settles the SAME tax-inclusive total the card leg was split from
133	   * — never re-derived after the card cleared. Absent on legacy/full-price sessions,
134	   * in which case the charge path recomputes it from the owner's country (0 by
135	   * default), which can only ever undertax, the conservative direction.
136	   */
137	  taxCents?: number;
138	  taxRatePercent?: number;
139	  taxCountry?: string;
140	};
