142	/**
143	 * The sold price implied by a quote — the ONE place a quote becomes a price. An
144	 * optional resolved tax context stamps the VAT the card round-trip must settle.
145	 */
146	export function orderPriceOf(
147	  quote: {
148	    chargeCents: number;
149	    promo: { discountPercent: number; name: string };
150	  },
151	  tax?: { taxCents: number; ratePercent: number; country: string } | null,
152	): OrderPrice {
153	  return {
154	    chargeCents: quote.chargeCents,
155	    promoPercent: quote.promo.discountPercent,
156	    promoName: quote.promo.name,
157	    ...(tax
158	      ? { taxCents: tax.taxCents, taxRatePercent: tax.ratePercent, taxCountry: tax.country }
159	      : {}),
160	  };
161	}
