163	/**
164	 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
165	 * well-formed: a half-parsed price would be worse than no price at all, because
166	 * the caller's fallback (re-quote) is at least internally consistent.
167	 */
168	export function parseOrderPrice(raw: unknown): OrderPrice | null {
169	  let obj: unknown = raw;
170	  if (typeof raw === "string") {
171	    try {
172	      obj = JSON.parse(raw);
173	    } catch {
174	      return null;
175	    }
176	  }
177	  if (!obj || typeof obj !== "object") return null;
178	  const { chargeCents, promoPercent, promoName, taxCents, taxRatePercent, taxCountry } =
179	    obj as Record<string, unknown>;
180	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
181	  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
182	  if (promoPercent < 0 || promoPercent > 100) return null;
183	  // Tax fields are ADDITIVE and lenient: a session written before Finding 1 (or with a
184	  // malformed tax field) carries none, and the charge path recomputes tax from the
185	  // owner's country — which undertaxes at worst, never overcharges.
186	  const tc = typeof taxCents === "number" && Number.isInteger(taxCents) && taxCents >= 0 ? taxCents : 0;
187	  const tr =
188	    typeof taxRatePercent === "number" && Number.isFinite(taxRatePercent) && taxRatePercent >= 0
189	      ? taxRatePercent
190	      : 0;
191	  return {
192	    chargeCents,
193	    promoPercent,
194	    promoName: typeof promoName === "string" ? promoName : "",
195	    taxCents: tc,
196	    taxRatePercent: tr,
197	    taxCountry: typeof taxCountry === "string" ? taxCountry : "",
198	  };
199	}
