68	/** Stripe brand ids are lowercase slugs ("visa", "amex", "unionpay"). */
69	export function brandLabel(brand: string | null | undefined): string {
70	  const map: Record<string, string> = {
71	    visa: "Visa",
72	    mastercard: "Mastercard",
73	    amex: "American Express",
74	    discover: "Discover",
75	    diners: "Diners Club",
76	    jcb: "JCB",
77	    unionpay: "UnionPay",
78	    cartes_bancaires: "Cartes Bancaires",
79	    eftpos_au: "Eftpos",
80	    link: "Link",
81	  };
82	  if (!brand) return "Card";
83	  return map[brand] ?? brand.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
84	}
