128	/** True when this account can actually be charged off-session right now. */
129	export function hasChargeableCard(user: {
130	  stripeCustomerId: string | null;
131	  stripePaymentMethodId: string | null;
132	}): boolean {
133	  return stripeConfigured() && !!user.stripeCustomerId && !!user.stripePaymentMethodId;
