165	/**
166	 * Hosted Checkout session in `mode: "setup"` — how a customer saves a card.
167	 *
168	 * Checkout rather than Stripe Elements because there is no Elements/Stripe.js
169	 * integration anywhere in this codebase and no publishable key plumbed to the
170	 * browser; a redirect to Stripe's own page reuses the exact flow that already
171	 * takes money for deploys, upgrades and top-ups.
172	 *
173	 * `usage: "off_session"` is load-bearing: it records a mandate that covers the
174	 * unattended renewal charges we make later. Without it many issuers (and every
175	 * SCA-regulated card) reject the first off-session charge outright, which would
176	 * turn "saved card" into "card that is declined once a month".
177	 */
178	export async function createCardSetupSession(
179	  user: CardUser,
180	  returnPath = "/dashboard/billing",
181	): Promise<string | null> {
182	  if (!stripeConfigured()) return null;
183	  const customerId = await ensureStripeCustomer(user);
184	  const base = appBase();
185	  const session = await stripe().checkout.sessions.create({
186	    mode: "setup",
187	    customer: customerId,
188	    payment_method_types: ["card"],
189	    setup_intent_data: { metadata: { nxeonUserId: user.id } },
190	    metadata: { nxeonUserId: user.id, nxeonCardSetup: "1" },
191	    // Deliberately NOT /api/stripe/confirm. A setup session has no amount and
192	    // `payment_status: "unpaid"`, so the shared fulfil path would classify it as a
193	    // wallet top-up and flash "Payment received — your balance updates within
194	    // seconds" at someone who only saved a card. We finalise through our own
195	    // server action instead.
196	    success_url: `${base}${returnPath}?card_setup={CHECKOUT_SESSION_ID}`,
197	    cancel_url: `${base}${returnPath}?card_setup=canceled`,
198	  });
199	  return session.url;
200	}
