202	/** Mirror the display fields + payment method for a card onto the account. */
203	async function persistCard(userId: string, customerId: string, pm: Stripe.PaymentMethod) {
204	  await db.user.update({
205	    where: { id: userId },
206	    data: {
207	      stripeCustomerId: customerId,
208	      stripePaymentMethodId: pm.id,
209	      cardBrand: pm.card?.brand ?? null,
210	      cardLast4: pm.card?.last4 ?? null,
211	      cardExpMonth: pm.card?.exp_month ?? null,
212	      cardExpYear: pm.card?.exp_year ?? null,
213	      // A brand-new card gets a fresh expiry-warning budget, otherwise a customer
214	      // who replaces an expiring card would never be warned about the new one.
215	      cardExpiryNotifiedAt: null,
216	    },
217	  });
218	}
