220	export type SavedCard = { brand: string | null; last4: string | null; expMonth: number | null; expYear: number | null };
221	
222	/**
223	 * Finalise a completed setup Checkout session: read the payment method off it,
224	 * make it the customer's default and mirror it onto the account.
225	 *
226	 * Verifies `metadata.nxeonUserId` against the caller. The session id travels in a
227	 * URL the customer can edit, so without that check a customer could paste someone
228	 * else's session id and attach their card to their own account.
229	 */
230	export async function saveCardFromSetupSession(
231	  sessionId: string,
232	  userId: string,
233	): Promise<{ card?: SavedCard; error?: string }> {
234	  if (!stripeConfigured()) return { error: "Card payments are not configured." };
235	  let session: Stripe.Checkout.Session;
236	  try {
237	    session = await stripe().checkout.sessions.retrieve(sessionId, { expand: ["setup_intent"] });
238	  } catch {
239	    return { error: "We couldn't read that card setup. Try adding the card again." };
240	  }
241	  if (session.mode !== "setup" || session.metadata?.nxeonUserId !== userId) {
242	    return { error: "That card setup doesn't belong to this account." };
243	  }
244	  if (session.status !== "complete") {
245	    return { error: "The card wasn't saved — the setup wasn't completed." };
246	  }
247	  const setupIntent = session.setup_intent as Stripe.SetupIntent | string | null;
248	  const pmRef =
249	    typeof setupIntent === "string" ? null : (setupIntent?.payment_method ?? null);
250	  const pmId = typeof pmRef === "string" ? pmRef : (pmRef?.id ?? null);
251	  const customerId =
252	    typeof session.customer === "string" ? session.customer : (session.customer?.id ?? null);
253	  if (!pmId || !customerId) return { error: "The card wasn't saved — no payment method came back." };
254	
255	  const pm = await stripe().paymentMethods.retrieve(pmId);
256	  // Checkout already attached the method to the customer; making it the default
257	  // means the adoption backstop below and anything Stripe-side pick the same card.
258	  await stripe()
259	    .customers.update(customerId, { invoice_settings: { default_payment_method: pmId } })
260	    .catch(() => {
261	      /* non-fatal: our own stripePaymentMethodId is the source of truth for charging */
262	    });
263	  await persistCard(userId, customerId, pm);
264	  return {
265	    card: {
266	      brand: pm.card?.brand ?? null,
267	      last4: pm.card?.last4 ?? null,
268	      expMonth: pm.card?.exp_month ?? null,
269	      expYear: pm.card?.exp_year ?? null,
270	    },
271	  };
272	}
