274	/**
275	 * Backstop for the closed-tab case.
276	 *
277	 * Checkout attaches the card to the Stripe customer BEFORE our `success_url` ever
278	 * runs. A customer who completes the Stripe page and then closes the tab has a
279	 * perfectly good card on file at Stripe and none on file here — and would be
280	 * dunned and suspended for it. This is the same class of bug as the Stripe
281	 * fulfilment incident: a browser redirect must never be the only trigger.
282	 *
283	 * Adoption is deliberately narrow. It requires a `card.setup_started` audit row
284	 * newer than any `card.removed` row and no older than a week, so a card the
285	 * customer explicitly REMOVED can never be silently resurrected and charged.
286	 */
287	export async function adoptUnclaimedCards(now = new Date()): Promise<number> {
288	  if (!stripeConfigured()) return 0;
289	  const since = new Date(now.getTime() - SETUP_INTENT_TTL_DAYS * 86400_000);
290	  const starts = await db.auditLog.findMany({
291	    where: { action: CARD_SETUP_STARTED, createdAt: { gt: since } },
292	    orderBy: { createdAt: "desc" },
293	    take: 200,
294	  });
295	  const userIds = [...new Set(starts.map((a) => a.userId).filter((v): v is string => !!v))];
296	  if (userIds.length === 0) return 0;
297	
298	  let adopted = 0;
299	  for (const userId of userIds) {
300	    const user = await db.user.findUnique({ where: { id: userId } });
301	    if (!user?.stripeCustomerId || user.stripePaymentMethodId) continue;
302	
303	    const startedAt = starts.find((a) => a.userId === userId)!.createdAt;
304	    const removed = await db.auditLog.findFirst({
305	      where: { userId, action: CARD_REMOVED },
306	      orderBy: { createdAt: "desc" },
307	    });
308	    if (removed && removed.createdAt > startedAt) continue; // removal is the later intent
309	
310	    try {
311	      const list = await stripe().paymentMethods.list({
312	        customer: user.stripeCustomerId,
313	        type: "card",
314	        limit: 5,
315	      });
316	      const pm = list.data[0]; // newest first
317	      if (!pm) continue;
318	      await persistCard(userId, user.stripeCustomerId, pm);
319	      await db.auditLog.create({
320	        data: {
321	          userId,
322	          action: "card.adopted",
323	          detail: `${cardDisplayLabel({
324	            brand: pm.card?.brand ?? null,
325	            last4: pm.card?.last4 ?? null,
326	            expMonth: pm.card?.exp_month ?? null,
327	            expYear: pm.card?.exp_year ?? null,
328	          })} (saved at Stripe but never confirmed in the browser)`,
329	        },
330	      });
331	      adopted++;
332	    } catch (e) {
333	      console.error(`[cards] could not adopt card for ${userId}`, e);
334	    }
335	  }
336	  return adopted;
337	}
