339	/**
340	 * Remove the saved card: detach at Stripe FIRST, and only clear our columns once
341	 * Stripe agrees the method is gone. Clearing locally while the method is still
342	 * attached would let `adoptUnclaimedCards` re-adopt it and charge a card the
343	 * customer had removed. A method that is already missing counts as removed.
344	 */
345	export async function detachSavedCard(userId: string): Promise<{ ok?: true; error?: string }> {
346	  const user = await db.user.findUnique({ where: { id: userId } });
347	  if (!user) return { error: "Account not found." };
348	  if (!user.stripePaymentMethodId) {
349	    await clearCardColumns(userId);
350	    return { ok: true };
351	  }
352	  if (stripeConfigured()) {
353	    try {
354	      await stripe().paymentMethods.detach(user.stripePaymentMethodId);
355	    } catch (e) {
356	      const err = asStripeError(e);
357	      if (err?.code !== "resource_missing") {
358	        console.error("[cards] detach failed", e);
359	        return { error: "We couldn't remove the card just now. Please try again in a moment." };
360	      }
361	    }
362	  }
363	  await clearCardColumns(userId);
364	  return { ok: true };
365	}
