367	async function clearCardColumns(userId: string) {
368	  await db.user.update({
369	    where: { id: userId },
370	    data: {
371	      stripePaymentMethodId: null,
372	      cardBrand: null,
373	      cardLast4: null,
374	      cardExpMonth: null,
375	      cardExpYear: null,
376	      cardExpiryNotifiedAt: null,
377	    },
378	  });
379	}
