381	/**
382	 * A customer who saves a card mid-dunning has been told (by
383	 * `emails.paymentFailed`) that we'll "charge it straight away". Bringing the
384	 * scheduled retry forward is what makes that copy true — the next sweep picks it
385	 * up instead of waiting for the day-3 or day-5 slot. The failure COUNT is left
386	 * alone: the money is still owed.
387	 */
388	export async function retryDunningNow(userId: string): Promise<number> {
389	  const res = await db.server.updateMany({
390	    where: { userId, dunningStage: { gt: 0 } },
391	    data: { dunningNextAt: new Date() },
392	  });
393	  return res.count;
394	}
