396	/* ------------------------------------------------------------------ *
397	 * Off-session charging
398	 * ------------------------------------------------------------------ */
399	
400	type StripeErrorLike = {
401	  type?: string;
402	  rawType?: string;
403	  code?: string;
404	  decline_code?: string;
405	  message?: string;
406	  payment_intent?: { id?: string; status?: string };
407	};
408	
409	function asStripeError(e: unknown): StripeErrorLike | null {
410	  if (!e || typeof e !== "object") return null;
411	  const err = e as StripeErrorLike;
412	  return err.rawType || err.type?.startsWith("Stripe") ? err : null;
413	}
414	
415	export type OffSessionResult =
416	  /** Money captured. `amountCents` is what Stripe actually took, not what we asked for. */
417	  | { ok: true; paymentIntentId: string; amountCents: number; replayed: boolean }
418	  /** 3-D Secure or equivalent: the customer must approve it with their bank. */
419	  | { ok: false; kind: "requires_action"; paymentIntentId: string | null; message: string }
420	  /** The issuer said no. A real dunning event. */
421	  | { ok: false; kind: "declined"; message: string; code?: string }
422	  /** Our side or Stripe's side wobbled. NOT the customer's fault — never dun for it. */
423	  | { ok: false; kind: "transient"; message: string }
424	  /** Nothing to charge with (no card, Stripe off, amount under Stripe's floor). */
425	  | { ok: false; kind: "unavailable"; message: string };
426	
427	/**
428	 * Stable per-purpose marker written into PaymentIntent metadata.
429	 *
430	 * This is a SECOND idempotency guard that does not expire. Stripe's own
431	 * idempotency keys are only honoured for 24 hours, and our dunning schedule spans
432	 * six days, so the key alone cannot answer "have we already been paid for this
433	 * period?". Before charging we look for a live PaymentIntent carrying this marker
434	 * and reuse it — so a crash between "Stripe captured the money" and "we recorded
435	 * the payment intent id" can never turn into a second charge.
436	 */
437	export function renewalChargeMarker(serverId: string, periodStart: Date): string {
438	  return `renew:${serverId}:${periodStart.toISOString()}`;
439	}
440	
441	/** Marker for an automatic wallet top-up: at most one per account per day. */
442	export function autoRechargeMarker(userId: string, now: Date): string {
443	  return `autorecharge:${userId}:${now.toISOString().slice(0, 10)}`;
444	}
445	
446	/** Look for a charge we may already have made for this exact purpose. */
447	async function findChargeByMarker(
448	  customerId: string,
449	  marker: string,
450	): Promise<Stripe.PaymentIntent | null> {
451	  // Stripe's maximum page size, and it is the number that matters rather than a
452	  // comfortable-looking one. This lookup is the guard that DOES NOT EXPIRE, and it
453	  // is the only one covering the gap between a day-3 retry and the day-5 retry —
454	  // Stripe honours an idempotency key for just 24 hours while the dunning ladder
455	  // runs six days. It was 25 on the reasoning that "renewals are monthly", which
456	  // holds per server and not per CUSTOMER: this list is scoped to the customer, so
457	  // an account with thirty servers renewing in one sweep pushes the marker off the
458	  // first page and the permanent guard silently stops guarding — at which point a
459	  // crash between "Stripe captured" and "we recorded it" charges the card twice for
460	  // one period.
461	  const list = await stripe().paymentIntents.list({ customer: customerId, limit: 100 });
462	  const mine = list.data.filter((pi) => pi.metadata?.nxeonChargeKey === marker);
463	  return (
464	    mine.find((pi) => pi.status === "succeeded") ??
465	    mine.find((pi) => pi.status === "requires_action") ??
466	    mine.find((pi) => pi.status === "processing") ??
467	    null
468	  );
469	}
470	
471	/**
472	 * Charge the saved card off-session (no customer present).
473	 *
474	 * Two independent idempotency guards, because this moves real money on a timer
475	 * that retries:
476	 *  1. `marker` — pre-flight lookup of a live PaymentIntent for this exact purpose.
477	 *     Survives forever, catches the crash-after-capture window.
478	 *  2. `idempotencyKey` — Stripe replays the identical request instead of charging
479	 *     twice when two sweeps overlap. Only good for 24h, hence guard 1.
480	 */
481	export async function chargeSavedCardOffSession(opts: {
482	  user: CardUser;
483	  amountCents: number;
484	  description: string;
485	  marker: string;
486	  idempotencyKey: string;
487	  metadata?: Record<string, string>;
488	}): Promise<OffSessionResult> {
489	  const { user, amountCents, description, marker, idempotencyKey } = opts;
490	  if (!stripeConfigured()) return { ok: false, kind: "unavailable", message: "Stripe is not configured" };
491	  if (!user.stripeCustomerId || !user.stripePaymentMethodId) {
492	    return { ok: false, kind: "unavailable", message: "No saved card" };
493	  }
494	  // `walletSplit` already keeps the card leg at or above Stripe's floor; this is
495	  // the belt-and-braces check so a future caller can't send a rejectable amount.
496	  if (amountCents < STRIPE_MIN_CENTS) {
497	    return { ok: false, kind: "unavailable", message: `Below Stripe minimum (${STRIPE_MIN_CENTS}c)` };
498	  }
499	
500	  // Guard 1: did we already charge for this purpose?
501	  try {
502	    const existing = await findChargeByMarker(user.stripeCustomerId, marker);
503	    if (existing?.status === "succeeded") {
504	      return {
505	        ok: true,
506	        paymentIntentId: existing.id,
507	        amountCents: existing.amount_received || existing.amount,
508	        replayed: true,
509	      };
510	    }
511	    if (existing?.status === "requires_action") {
512	      // A 3-D Secure wall does not move: retrying the SAME card off-session hits it
513	      // again, so reuse the existing intent (and its link) rather than piling up a
514	      // new challenge every retry. A DIFFERENT card is a different story — if the
515	      // customer has since saved one, cancel the stale challenge and really try it,
516	      // otherwise saving a new card would silently change nothing.
517	      const pendingPm =
518	        typeof existing.payment_method === "string"
519	          ? existing.payment_method
520	          : (existing.payment_method?.id ?? null);
521	      if (pendingPm === user.stripePaymentMethodId) {
522	        return {
523	          ok: false,
524	          kind: "requires_action",
525	          paymentIntentId: existing.id,
526	          message: "Awaiting bank confirmation",
527	        };
528	      }
529	      await cancelIfUnconfirmed(existing.id);
530	    }
531	    if (existing?.status === "processing") {
532	      return { ok: false, kind: "transient", message: "A charge for this period is still settling" };
533	    }
534	  } catch (e) {
535	    // A failed lookup must not become a blind second charge.
536	    console.error("[cards] pre-flight charge lookup failed", e);
537	    return { ok: false, kind: "transient", message: "Could not verify existing charges" };
538	  }
539	
540	  try {
541	    const pi = await stripe().paymentIntents.create(
542	      {
543	        amount: amountCents,
544	        currency: "usd",
545	        customer: user.stripeCustomerId,
546	        payment_method: user.stripePaymentMethodId,
547	        confirm: true,
548	        off_session: true,
549	        // No browser exists here, so a redirect-based next_action could never be
550	        // satisfied — and asking for one is what makes Stripe demand a return_url.
551	        automatic_payment_methods: { enabled: true, allow_redirects: "never" },
552	        description,
553	        metadata: { ...(opts.metadata ?? {}), nxeonUserId: user.id, nxeonChargeKey: marker },
554	      },
555	      { idempotencyKey },
556	    );
557	    if (pi.status === "succeeded") {
558	      return { ok: true, paymentIntentId: pi.id, amountCents: pi.amount_received || pi.amount, replayed: false };
559	    }
560	    if (pi.status === "requires_action" || pi.status === "requires_confirmation") {
561	      return { ok: false, kind: "requires_action", paymentIntentId: pi.id, message: "Bank confirmation required" };
562	    }
563	    if (pi.status === "processing") {
564	      return { ok: false, kind: "transient", message: "Payment is still processing" };
565	    }
566	    return { ok: false, kind: "declined", message: `Payment could not be completed (${pi.status})` };
567	  } catch (e) {
568	    return classifyChargeError(e);
569	  }
570	}
571	
572	/**
573	 * Split a charge failure into the three cases that deserve different treatment:
574	 * the bank wants the customer to confirm, the bank said no, or nothing about the
575	 * customer went wrong at all.
576	 *
577	 * The default is `transient` on purpose. A misclassified transient error costs us
578	 * a delayed renewal; a misclassified decline costs a paid-up customer their
579	 * server. Unknown always resolves to the direction that cannot suspend anyone.
580	 */
581	function classifyChargeError(e: unknown): OffSessionResult {
582	  const err = asStripeError(e);
583	  const message = String(err?.message ?? (e as Error)?.message ?? e).slice(0, 300);
584	  if (!err) return { ok: false, kind: "transient", message };
585	
586	  // 3-D Secure surfaces as a card error with this code, with the PI attached.
587	  if (err.code === "authentication_required" || err.payment_intent?.status === "requires_action") {
588	    return {
589	      ok: false,
590	      kind: "requires_action",
591	      paymentIntentId: err.payment_intent?.id ?? null,
592	      message,
593	    };
594	  }
595	  if (err.rawType === "card_error") {
596	    return { ok: false, kind: "declined", message, code: err.decline_code ?? err.code };
597	  }
598	  // The saved method vanished at Stripe (detached elsewhere, customer deleted).
599	  // Not a decline — there is nothing to retry until a new card is saved.
600	  if (err.rawType === "invalid_request_error" && err.code === "resource_missing") {
