680	/**
681	 * Hosted Checkout link for an outstanding renewal balance.
682	 *
683	 * Carries ONLY `nxeonUserId` in metadata, which makes the shared, already-proven
684	 * fulfilment path treat it as a wallet top-up: the money lands as wallet credit
685	 * and the next sweep renews from the wallet. That is why this is also the answer
686	 * to 3-D Secure — Checkout collects the bank challenge on Stripe's own page, so we
687	 * never need Stripe.js in the browser or a second confirmation code path.
688	 *
689	 * The quoted amount is the remainder the wallet cannot cover AT THIS MOMENT. If
690	 * the customer spends their credit before paying, the next sweep simply recomputes
691	 * the split and asks the card for the new remainder — it self-heals rather than
692	 * over- or under-charging.
693	 */
694	export async function createOutstandingCheckout(opts: {
695	  user: { id: string; email: string; stripeCustomerId: string | null };
696	  amountCents: number;
697	  hostname: string;
698	  serverId: string;
699	}): Promise<string | null> {
700	  if (!stripeConfigured()) return null;
701	  // Guard the INPUT, not the floored amount. `if (amount <= 0)` sat AFTER the
702	  // `Math.max(STRIPE_MIN_CENTS, …)` below and was therefore dead code: an
703	  // `amountCents` of 0 — a caller whose wallet already covers the renewal, or one
704	  // whose split came back with no card leg — was floored up to 50c and became a
705	  // real hosted-checkout page asking a customer who owes nothing for fifty cents.
706	  // Nothing due means no link, not a minimum charge.
707	  const due = Math.round(opts.amountCents);
708	  if (!Number.isFinite(due) || due <= 0) return null;
709	  // Stripe rejects a charge under its floor, and the surplus is honest here in a
710	  // way it would not be elsewhere: this session credits the WALLET, so a 30c
711	  // balance settled with the 50c minimum leaves the customer 20c of their own
712	  // credit, not 20c of our revenue. The page states the amount it charges.
713	  const amount = Math.max(STRIPE_MIN_CENTS, due);
714	  const base = appBase();
715	  try {
716	    const session = await stripe().checkout.sessions.create({
717	      mode: "payment",
718	      ...(opts.user.stripeCustomerId
719	        ? { customer: opts.user.stripeCustomerId }
720	        : { customer_email: opts.user.email }),
721	      line_items: [
722	        {
723	          price_data: {
724	            currency: "usd",
725	            product_data: {
726	              name: `Nxeon renewal — ${opts.hostname}`,
727	              description:
728	                "Settles the outstanding renewal balance. Added to your Nxeon wallet and applied to this renewal automatically.",
729	            },
730	            unit_amount: amount,
731	          },
732	          quantity: 1,
733	        },
734	      ],
735	      metadata: { nxeonUserId: opts.user.id },
736	      success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
737	      cancel_url: `${base}/dashboard/servers/${opts.serverId}`,
738	    });
739	    return session.url;
740	  } catch (e) {
741	    console.error("[cards] could not create outstanding-balance checkout", e);
742	    return null;
743	  }
744	}
