export function hostingAppCatalog(): { slug: string; name: string; needsDb: boolean }[] {
  return Object.entries(APP_RECIPES).map(([slug, r]) => ({ slug, name: r.name, needsDb: r.needsDb }));
}

async function taskAppInstall(conn: Client, a: { id: string; username: string; primaryDomain: string; maxDatabases: number }, payload: string | null): Promise<string> {
  const p = JSON.parse(payload || "{}") as { slug?: string; dbName?: string; dbUser?: string; dbPassEnc?: string };
  const slug = String(p.slug ?? "");
  const recipe = APP_RECIPES[slug];
  if (!recipe) throw new Error("unknown app");
  if (recipe.needsDb) await assertDbCap(a.id, a.maxDatabases);
  const u = a.username;
  if (!isValidUnixUsername(u)) throw new Error("unsafe account");
  const { webroot } = accountPaths(u);
  const isBz2 = recipe.url.endsWith(".bz2");
  const tarFlags = `${isBz2 ? "xjf" : "xzf"} - ${recipe.strip ? `--strip-components=${recipe.strip}` : ""}`;
  // Download + extract into the webroot AS the account user (jailed).
  await run(conn, `download ${slug}`, `sudo -u ${u} -H bash -c "cd ${webroot} && curl -fsSL '${recipe.url}' | tar ${tarFlags}"`);
  let dbInfo = "";
  if (recipe.needsDb) {
    const dbName = String(p.dbName ?? "");
    const dbUser = String(p.dbUser ?? "");
    const dbPass = (p.dbPassEnc ? decryptSecret(p.dbPassEnc) : "") ?? "";
    if (!/^[a-z0-9_]{1,64}$/.test(dbName) || !/^[a-z0-9_]{1,32}$/.test(dbUser) || !/^[A-Za-z0-9]{1,64}$/.test(dbPass)) throw new Error("invalid db identifiers");
    const sql = sqlForMysqlExec(buildScopedGrantSql(dbName, dbUser, dbPass));
    await run(conn, "app db", `mysql -e "${sql}"`);
    await db.hostingDatabase.create({ data: { accountId: a.id, name: dbName, dbUser, passwordEnc: null, status: "ACTIVE" } }).catch(() => undefined);
    dbInfo = ` Database: ${dbName} · user ${dbUser} · password ${dbPass} (host localhost).`;
  }
  return JSON.stringify({ app: recipe.name, url: `https://${a.primaryDomain}/`, note: recipe.note + dbInfo });
}

