637	/**
638	 * Charge the saved card for the wallet shortfall, then renew.
639	 *
640	 * The card NEVER pays the invoice directly. It credits the wallet with exactly
641	 * what Stripe captured, and `commitRenewal` then debits the FULL renewal from the
642	 * wallet — identical to how checkout splits a purchase. That ordering is what
643	 * makes a crash safe in both directions: money captured but not yet applied sits
644	 * in the customer's wallet as credit (visible, spendable, refundable), and a
645	 * renewal can never be granted without a matching debit.
646	 *
647	 * TWO idempotency guards ride on every attempt:
648	 *  - `marker` (server + period) — a permanent pre-flight lookup at Stripe for a
649	 *    live PaymentIntent for this exact period, so a crash between "Stripe captured"
650	 *    and "we recorded it" replays instead of charging again.
651	 *  - `idempotencyKey` (server + period + attempt + amount) — Stripe replays an
652	 *    identical request for 24h, which covers two overlapping sweeps of the SAME
653	 *    scheduled attempt. The attempt and amount are in the key because a genuine
654	 *    day-3 retry, or a retry for a different remainder after the wallet moved, is a
655	 *    deliberately NEW charge; reusing the key there would make Stripe reject it.
656	 *
657	 * And the credit itself is guarded by the UNIQUE index on
658	 * `WalletTransaction.stripePaymentIntentId`, so even a replayed capture credits once.
659	 *
660	 * @returns true when the term was actually extended.
661	 */
662	async function attemptCardRenewal(opts: {
663	  server: DueServer;
664	  charge: RenewalCharge;
665	  cardCents: number;
666	  newExpiry: Date;
667	  now: Date;
668	  cfg: DunningConfig;
669	  /** Destination country the VAT was charged for; passed through to the invoice. */
670	  taxCountry?: string;
671	}): Promise<boolean> {
672	  const { server, charge, cardCents, newExpiry, now, cfg, taxCountry } = opts;
673	  const user = server.user;
674	  const periodStart = server.expiresAt!;
675	  const marker = renewalChargeMarker(server.id, periodStart);
676	  const idempotencyKey = `nxeon_renew_${server.id}_${periodStart.getTime()}_a${server.dunningStage}_${cardCents}`;
677	  const cardLabel = savedCardLabel(user) ?? "your saved card";
678	
679	  const result = await chargeSavedCardOffSession({
680	    user,
681	    amountCents: cardCents,
682	    description: `Renewal: ${charge.label} (${server.hostname})`,
683	    marker,
684	    idempotencyKey,
685	    metadata: {
686	      nxeonServerId: server.id,
687	      nxeonPeriodStart: periodStart.toISOString(),
688	      nxeonKind: "renewal",
689	    },
690	  });
