import { placeHostingOrder, startHostingCardSetup } from "@/lib/actions-hosting";
import { finalizeCardSetup } from "@/lib/actions-payment-method";
import { termPriceCents, ANNUAL_TERM_MONTHS, DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
import { TermLadder } from "@/components/customer/TermLadder";
import { recommendHostingPlan } from "@/lib/hosting/recommend";

/* --------------------------------------------------------------- types --- */

export type WizardPlan = {
  id: string;
  name: string;
  priceCents: number;
  diskGB: number;
  maxSites: number;
  maxDatabases: number;
  bandwidthTB: number;
  mailboxes: number;
  freeMigration: boolean;
  featured: boolean;
  tagline: string;
};

type AppOpt = { slug: string; name: string; needsDb: boolean };

const money = (c: number) => `$${(c / 100).toFixed(2)}`;

/** sessionStorage key for the in-progress order — survives the Stripe card round-trip. */
const DRAFT_KEY = "nxeon.hosting.deploy.draft.v1";
type Draft = {
  step: number;
  planId: string;
  termMonths: number;
  domainMode: "temp" | "own";
  domain: string;
  appSlug: string;
};

/**
 * The one-month first-month-free credit, computed EXACTLY like the server's
 * `firstMonthCreditCents` (kept inline so this client file never imports the
 * db-backed promo module). A 1-month term is wholly free; a longer term credits a
 * single month. The server recomputes the real debit with the same formula, so
 * displayed === charged.
 */
function firstMonthCredit(fullCents: number, months: number): number {
  if (months <= 1) return fullCents;
  return Math.min(fullCents, Math.round(fullCents / months));
}

function Stepper({ step, steps }: { step: number; steps: string[] }) {
  return (
    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
      {steps.map((s, i) => (
        <div key={s} className="flex items-center gap-2">
          <span
            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
              i === step
                ? "border-brand-400 bg-brand-500/20 text-brand-200"
                : i < step
                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
                  : "border-white/10 text-slate-500"
            }`}
          >
            {i < step ? "✓" : i + 1}
          </span>
          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
        </div>
      ))}
    </div>
  );
}

/* -------------------------------------------------------------- wizard --- */

export function HostingDeployWizard({
  plans,
  apps,
  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
  firstMonthFree = false,
  balanceCents,
  hasCard,
  cardLabel,
  stripeReady,
  tempSubdomainBase,
}: {
  plans: WizardPlan[];
  apps: AppOpt[];
  annualDiscountPct?: number;
  firstMonthFree?: boolean;
  balanceCents: number;
  /** A renewal-capable card is already on file (charged off-session at renewal). */
  hasCard: boolean;
  cardLabel: string | null;
  /** Stripe is configured, so we can capture a card at all. */
  stripeReady: boolean;
  /** Base zone for the free temporary subdomain, e.g. "nxeon.cloud". */
  tempSubdomainBase: string;
}) {
  // Steps: Install is only shown when there's an app catalog to pick from.
  const hasApps = apps.length > 0;
  const steps = ["Plan", "Domain", ...(hasApps ? ["Install"] : []), "Add-ons", "Review"];
  const [step, setStep] = useState(0);

  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
  const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
  const [domainMode, setDomainMode] = useState<"temp" | "own">("temp");
  const [domain, setDomain] = useState("");
  const [appSlug, setAppSlug] = useState("");

  // A card the customer just saved via the Stripe round-trip flips this true
  // without a page reload, so the Review step stops asking for one.
  const [savedCard, setSavedCard] = useState(hasCard);

  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [cardBusy, setCardBusy] = useState(false);
  const [cardNote, setCardNote] = useState("");
  const [restoredAfterSetup, setRestoredAfterSetup] = useState(false);

  // ONE idempotency token per wizard mount. A double-click is stopped by `busy`;
  // this token is the server-side guard against a network retry creating a second
  // account (placeHostingOrder → FulfilledSession UNIQUE). A user-driven retry
  // after a failure reuses it safely (the server clears a FAILED marker).
  const idemRef = useRef<string>("");
  if (!idemRef.current) idemRef.current = makeToken();

  const plan = plans.find((p) => p.id === planId) ?? null;
  const curLabel = steps[step];
  const isLast = step === steps.length - 1;

  /* ----- pricing (all DB-fed; the server recomputes the debit identically) -- */
  const fullTermCents = plan ? termPriceCents(plan.priceCents, termMonths, annualDiscountPct) : 0;
  const creditCents = firstMonthFree ? firstMonthCredit(fullTermCents, termMonths) : 0;
  const dueTodayCents = Math.max(0, fullTermCents - creditCents);
  // What the account renews at — the full term price, unchanged by the promo.
  const renewalCents = fullTermCents;
  const perMonthCents = Math.round(fullTermCents / Math.max(1, termMonths));
  const termWord = termMonths === ANNUAL_TERM_MONTHS ? "year" : termMonths === 1 ? "month" : `${termMonths} mo`;

  // Can we bill the renewal? A saved card OR a wallet already holding a renewal's
  // worth. This mirrors the server gate in placeHostingOrder exactly.
  const renewalMethodOk = savedCard || balanceCents >= renewalCents;

  /* ----- Stripe card round-trip (draft save + restore) ---------------------- */
  useEffect(() => {
    let sid = "";
    try {
      sid = new URLSearchParams(window.location.search).get("card_setup") ?? "";
    } catch {
      /* no URL access */
    }
    if (!sid) return;
    // Pull our draft back so the customer lands where they left off.
    let d: Draft | null = null;
    try {
      const raw = sessionStorage.getItem(DRAFT_KEY);
      sessionStorage.removeItem(DRAFT_KEY);
      if (raw) d = JSON.parse(raw) as Draft;
    } catch {
      d = null;
    }
    if (d) {
      if (plans.some((p) => p.id === d.planId)) setPlanId(d.planId);
      if (d.termMonths === 1 || d.termMonths === ANNUAL_TERM_MONTHS) setTermMonths(d.termMonths);
      if (d.domainMode === "temp" || d.domainMode === "own") setDomainMode(d.domainMode);
      if (typeof d.domain === "string") setDomain(d.domain);
      if (apps.some((a) => a.slug === d.appSlug)) setAppSlug(d.appSlug);
    }
    setRestoredAfterSetup(true);
    setStep(steps.length - 1); // land on Review
    if (sid === "canceled") {
      setCardNote("Card setup was cancelled — you weren’t charged. Add a card to enable renewals, or use your wallet.");
      return;
    }
    // Finalise the saved card, then reflect it on the Review step.
    (async () => {
      const res = await finalizeCardSetup(sid);
      if (res.ok) {
        setSavedCard(true);
        setCardNote(`Card saved${res.label ? ` — ${res.label}` : ""}. Your renewals will bill to it.`);
      } else {
        setCardNote(res.error ?? "We couldn’t save that card. Try again or use your wallet.");
      }
    })();
    // Mount-only restore.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function saveDraft() {
    try {
      const d: Draft = { step, planId, termMonths, domainMode, domain, appSlug };
      sessionStorage.setItem(DRAFT_KEY, JSON.stringify(d));
    } catch {
      /* storage disabled — the card flow still works, it just won't restore */
    }
  }

  async function addCard() {
    setCardBusy(true);
    setCardNote("");
    saveDraft();
    try {
      const res = await startHostingCardSetup();
      if (res.url) {
        window.location.href = res.url;
        return;
      }
      setCardNote(res.error ?? "We couldn’t start card setup just now. Please try again.");
    } catch {
      setCardNote("We couldn’t start card setup just now. Please try again.");
    } finally {
      setCardBusy(false);
    }
  }

  /* ----- domain validity (client-side friendliness; server re-validates) ---- */
  const domainTrim = domain.trim().toLowerCase();
  const domainLooksValid = /^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$/.test(domainTrim);
  const domainBlocker =
    domainMode === "own" && !domainLooksValid
      ? domainTrim.length === 0
        ? "Enter the domain you want to host, or switch to a free temporary subdomain."
        : "Enter a valid domain (e.g. example.com)."
      : null;

  const canContinue = curLabel === "Domain" ? !domainBlocker : true;
  const canPlace = !!planId && !busy && !domainBlocker;

  async function place() {
    if (!plan) return;
    setBusy(true);
    setError("");
    try {
      const res = await placeHostingOrder({
        planId,
        domain: domainMode === "own" ? domainTrim : undefined,
        termMonths,
        appSlug: appSlug || undefined,
        idempotencyKey: idemRef.current,
      });
      if ("ok" in res && res.ok) {
        try {
          sessionStorage.removeItem(DRAFT_KEY);
        } catch {
          /* ignore */
        }
        window.location.href = `/dashboard/hosting/${res.accountId}`;
        return;
      }
      if ("needCard" in res) {
        setCardNote("Add a renewal payment method to continue — a $0 first month still needs a way to bill month two.");
        setStep(steps.length - 1);
        return;
      }
      setError(res.error ?? "Something went wrong. Your wallet was not charged — try again.");
    } catch {
      setError("Something went wrong. Your wallet was not charged — try again.");
    } finally {
      setBusy(false);
    }
  }

  const domainForReview =
    domainMode === "own"
      ? domainTrim || "—"
      : `a free ${tempSubdomainBase} subdomain (connect a real domain anytime)`;
  const appName = apps.find((a) => a.slug === appSlug)?.name ?? "None";

  return (
    <div className="card">
      <Stepper step={step} steps={steps} />

      {restoredAfterSetup && cardNote && (
        <div className="mb-4 rounded-xl border border-white/[0.08] bg-white/[0.03] px-3 py-2 text-sm text-slate-300">{cardNote}</div>
      )}
      {error && <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}

      {/* -------------------------------------------------------- Plan --- */}
      {curLabel === "Plan" && (
        <div>
          <h2 className="mb-1 font-semibold">Choose your plan</h2>
          <p className="mb-4 text-sm text-slate-400">
            Each account is isolated with its own storage, databases and email. Commit longer to pay less per month —
            you can change the term below.
          </p>
          {plans.length === 0 ? (
            <p className="text-sm text-slate-400">No hosting plans are available yet. Check back soon.</p>
          ) : (
            <>
              <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
                {plans.map((p) => {
                  const rec = recommendHostingPlan(p);
                  const selected = planId === p.id;
                  return (
                    <button
                      key={p.id}
                      type="button"
                      onClick={() => setPlanId(p.id)}
                      className={`relative flex flex-col rounded-xl border px-4 py-3 text-left transition ${
                        selected ? "!border-brand-400 ring-1 ring-brand-400 bg-brand-500/10" : p.featured ? "border-brand-500/40 hover:border-brand-400" : "border-white/10 hover:border-white/20"
                      }`}
                    >
                      {p.featured && (
                        <span className="absolute -top-2 right-3 rounded-full bg-brand-500 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-white">
                          Most popular
                        </span>
                      )}
                      <div className="flex items-baseline justify-between gap-2">
                        <span className="font-medium">{p.name}</span>
                        {firstMonthFree ? (
                          <span className="text-right leading-tight">
                            <span className="block text-xs font-bold uppercase tracking-wide text-emerald-300">Free first month</span>
                            <span className="block text-[11px] text-slate-500">then {money(p.priceCents)}/mo</span>
                          </span>
                        ) : (
                          <span className="text-sm font-semibold">
                            {money(p.priceCents)}
                            <span className="text-xs text-slate-500">/mo</span>
                          </span>
                        )}
                      </div>
                      <p className="mt-1.5 text-xs font-medium text-brand-200">{p.tagline || rec.headline}</p>
                      <ul className="mt-2 space-y-0.5 text-xs text-slate-400">
                        <li>{p.diskGB} GB NVMe SSD storage</li>
                        <li>{p.maxSites} website{p.maxSites === 1 ? "" : "s"}</li>
                        <li>{p.maxDatabases} database{p.maxDatabases === 1 ? "" : "s"}</li>
                        <li>{p.bandwidthTB} TB bandwidth</li>
                        <li>{p.mailboxes} mailbox{p.mailboxes === 1 ? "" : "es"} · free SSL</li>
                        {p.freeMigration && <li className="text-emerald-300/90">✓ Free website migration</li>}
                      </ul>
                    </button>
                  );
                })}
              </div>
              {plan && (
                <div className="mt-5">
                  <div className="mb-1.5 flex items-baseline justify-between gap-2">
                    <label className="label mb-0">Billing term</label>
                    <span className="text-[11px] text-slate-500">Commit longer, pay less per month</span>
                  </div>
                  <TermLadder monthlyCents={plan.priceCents} annualDiscountPct={annualDiscountPct} value={termMonths} onChange={setTermMonths} />
                </div>
              )}
            </>
          )}
        </div>
      )}

      {/* ------------------------------------------------------ Domain --- */}
      {curLabel === "Domain" && (
        <div>
          <h2 className="mb-1 font-semibold">Where should your site live?</h2>
          <p className="mb-4 text-sm text-slate-400">
            You don’t need a domain to get started — begin on a free temporary subdomain and connect a real domain
            whenever you’re ready.
          </p>
          <div className="grid gap-3 sm:grid-cols-2">
            <button
              type="button"
              onClick={() => setDomainMode("temp")}
              className={`card p-4 text-left transition ${domainMode === "temp" ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}
            >
              <div className="mb-1 flex items-center justify-between">
                <span className="text-sm font-semibold">Free temporary subdomain</span>
                <span className="rounded bg-emerald-500/15 px-1.5 py-0.5 text-[10px] text-emerald-300">Recommended</span>
              </div>
              <p className="text-xs text-slate-400">
                Go live instantly on <span className="font-mono text-slate-300">yourname.{tempSubdomainBase}</span>. Add
                your own domain from the panel later — no re-order needed.
              </p>
            </button>
            <button
              type="button"
              onClick={() => setDomainMode("own")}
              className={`card p-4 text-left transition ${domainMode === "own" ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}
            >
              <div className="mb-1 flex items-center justify-between">
                <span className="text-sm font-semibold">Use my own domain</span>
              </div>
              <p className="text-xs text-slate-400">
                Already own a domain? Enter it and we’ll give you the exact DNS record to point it at us.
              </p>
            </button>
          </div>
          {domainMode === "own" && (
            <div className="mt-4 max-w-sm">
              <label className="label" htmlFor="hosting-domain">
                Your domain
              </label>
              <input
                id="hosting-domain"
                className="input"
                placeholder="example.com"
                value={domain}
                onChange={(e) => setDomain(e.target.value)}
                aria-invalid={!!domainBlocker}
              />
              {domainBlocker && <p className="mt-1 text-xs text-amber-300">{domainBlocker}</p>}
            </div>
          )}
        </div>
      )}

      {/* ----------------------------------------------------- Install --- */}
      {curLabel === "Install" && (
        <div>
          <h2 className="mb-1 font-semibold">One-click app install <span className="text-xs font-normal text-slate-500">optional</span></h2>
          <p className="mb-4 text-sm text-slate-400">Pick an app to auto-install once your account is ready. You can always install more later.</p>
          <div className="grid gap-2.5 sm:grid-cols-2 lg:grid-cols-3">
            <button
              type="button"
              onClick={() => setAppSlug("")}
              className={`card p-4 text-left transition ${appSlug === "" ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}
            >
              <span className="text-sm font-semibold">None for now</span>
              <p className="mt-1 text-xs text-slate-400">Start with an empty webroot.</p>
            </button>
            {apps.map((a) => {
              const on = appSlug === a.slug;
              return (
                <button
                  key={a.slug}
                  type="button"
                  onClick={() => setAppSlug(a.slug)}
                  className={`card p-4 text-left transition ${on ? "!border-brand-400 ring-1 ring-brand-400" : "hover:border-white/20"}`}
                >
                  <span className="text-sm font-semibold">{a.name}</span>
                  <p className="mt-1 text-xs text-slate-400">{a.needsDb ? "Includes a database, set up for you." : "Lightweight — no database needed."}</p>
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* ----------------------------------------------------- Add-ons --- */}
      {curLabel === "Add-ons" && (
        <div>
          <h2 className="mb-1 font-semibold">What’s included <span className="text-xs font-normal text-slate-500">optional</span></h2>
          <p className="mb-4 text-sm text-slate-400">Your plan already bundles the essentials. Need more room later? Upgrade your plan anytime — you only ever pay the plan price you signed up at.</p>
          <div className="grid gap-3 sm:grid-cols-2">
            {[
              { t: "Free SSL", d: "Automatic HTTPS on every domain and subdomain — issued and renewed for you." },
              { t: "Daily backups", d: "On-demand snapshots of your files and databases, restorable from the panel." },
              { t: `${plan?.mailboxes ?? 0} email mailbox${(plan?.mailboxes ?? 0) === 1 ? "" : "es"}`, d: "Real inboxes on your domain, included with the plan." },
              ...(plan?.freeMigration ? [{ t: "Free migration", d: "We’ll move an existing site across for you at no extra cost." }] : []),
            ].map((f) => (
              <div key={f.t} className="card p-4">
                <div className="mb-1 flex items-center justify-between">
                  <span className="text-sm font-semibold">{f.t}</span>
                  <span className="rounded bg-emerald-500/15 px-1.5 py-0.5 text-[10px] text-emerald-300">Included</span>
                </div>
                <p className="text-xs text-slate-400">{f.d}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ------------------------------------------------------ Review --- */}
      {curLabel === "Review" && plan && (
        <div>
          <h2 className="mb-4 font-semibold">Review &amp; checkout</h2>
          <dl className="space-y-2 text-sm">
            <Row k="Plan" v={`${plan.name} · ${plan.diskGB} GB · ${plan.maxSites} site${plan.maxSites === 1 ? "" : "s"}`} />
            <Row k="Billing term" v={`${termMonths === ANNUAL_TERM_MONTHS ? "Annual" : "Monthly"} · ${money(perMonthCents)}/mo`} />
            <Row k="Site address" v={domainForReview} />
            {hasApps && <Row k="App install" v={appName} />}
            <div className="divider" />
            {firstMonthFree && creditCents > 0 && (
              <Row k="First month free" v={<span className="text-emerald-300">−{money(creditCents)}</span>} />
            )}
            <Row
              k="Due today"
              v={<span className="text-base font-semibold">{money(dueTodayCents)}</span>}
            />
            <Row
              k="Renews"
              v={
                <span className="text-slate-300">
                  {money(renewalCents)} / {termWord}
                </span>
              }
            />
            {balanceCents > 0 && dueTodayCents > 0 && (
              <Row k="Wallet balance" v={<span className="text-slate-300">{money(balanceCents)}</span>} />
            )}
          </dl>

          {firstMonthFree && (
            <p className="mt-3 text-xs text-emerald-300/90">
              <span className="font-semibold">Free first month</span> — {money(dueTodayCents)} today, then {money(renewalCents)}/{termWord} when it renews. The price you sign up at is the price you renew at.
            </p>
          )}

          {/* Renewal payment method — the core money-safety gate. */}
          <div className="mt-5 rounded-xl border border-white/[0.08] bg-white/[0.02] p-4">
            <p className="text-sm font-semibold">Renewal payment method</p>
            {renewalMethodOk ? (
              <p className="mt-1 text-xs text-slate-400">
                {savedCard
                  ? `We’ll bill renewals to your card${cardLabel ? ` (${cardLabel})` : " on file"}.`
                  : `Your wallet balance (${money(balanceCents)}) covers your renewal. Renewals are charged from your wallet — add a card anytime for hands-off billing.`}
              </p>
            ) : (
              <>
                <p className="mt-1 text-xs text-amber-300">
                  A {money(dueTodayCents)} first charge still needs a way to bill your renewal ({money(renewalCents)}/{termWord}). Add a card, or top up your wallet to cover a renewal.
                </p>
                {cardNote && <p className="mt-2 text-xs text-slate-400">{cardNote}</p>}
                {stripeReady ? (
                  <button type="button" className="btn-secondary mt-3" disabled={cardBusy} onClick={addCard}>
                    {cardBusy ? "Opening secure checkout…" : "Add a card for renewals"}
                  </button>
                ) : (
                  <p className="mt-2 text-xs text-slate-500">Card payments aren’t configured here yet — top up your wallet to continue.</p>
                )}
              </>
            )}
          </div>
        </div>
      )}

      {/* ------------------------------------------------------ nav row --- */}
      <div className="mt-6 flex items-center justify-between">
        <button type="button" className="btn-ghost" disabled={step === 0} onClick={() => setStep((s) => Math.max(0, s - 1))}>
          ← Back
        </button>
        {!isLast ? (
          <button
            type="button"
            className="btn-primary"
            disabled={!canContinue || plans.length === 0}
            onClick={() => setStep((s) => s + 1)}
          >
            Continue →
          </button>
        ) : (
          <button
            type="button"
            className="btn-primary px-6"
            disabled={!canPlace || !renewalMethodOk}
            onClick={place}
          >
            {busy ? "Placing order…" : dueTodayCents > 0 ? `Place order — ${money(dueTodayCents)} today` : "Place order — $0 today"}
          </button>
        )}
      </div>
      {isLast && !renewalMethodOk && (
        <p className="mt-3 text-xs text-amber-300">Add a renewal payment method above to place your order.</p>
      )}
    </div>
  );
}

function Row({ k, v }: { k: string; v: React.ReactNode }) {
  return (
    <div className="flex items-center justify-between">
      <dt className="text-slate-400">{k}</dt>
      <dd className="text-right">{v}</dd>
    </div>
  );
}

/** A short URL-safe idempotency token (no external uuid dependency). */
function makeToken(): string {
  try {
    if (typeof crypto !== "undefined" && "randomUUID" in crypto) return crypto.randomUUID().replace(/-/g, "");
  } catch {
    /* fall through */
  }
  return `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 12)}`;
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { retryHostingProvision, type HostingAccountView } from "@/lib/actions-hosting";
import { Badge, EmptyState, StatusDot } from "@/components/ui/primitives";
import { DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
import { HostingDeployWizard, type WizardPlan } from "@/components/customer/HostingDeployWizard";

export function HostingClient({
  plans,
  accounts,
  apps,
  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
  firstMonthFree = false,
  balanceCents,
  hasCard,
  cardLabel,
  stripeReady,
  tempSubdomainBase,
}: {
  plans: WizardPlan[];
  accounts: HostingAccountView[];
  apps: { slug: string; name: string; needsDb: boolean }[];
  /** Live admin annual discount (%), so the Annual term shows the REAL price/savings. */
  annualDiscountPct?: number;
  /**
   * Is the first-month-free promo live for shared hosting? Resolved server-side
   * (firstMonthFreeAppliesTo("HOSTING") + owner toggle) so the "FREE first month"
   * copy shows ONLY when checkout will actually grant it. Display only — the charge
   * logic lives in orderHostingAccount; nothing here alters what is billed.
   */
  firstMonthFree?: boolean;
  /** The customer's wallet balance (renewal-source + gate math). */
  balanceCents: number;
  /** A renewal-capable card is on file (billed off-session at renewal). */
  hasCard: boolean;
  cardLabel: string | null;
  /** Stripe is configured, so a card can be captured for renewals. */
  stripeReady: boolean;
  tempSubdomainBase: string;
}) {
  const [error, setError] = useState("");

  async function retry(id: string) {
    setError("");
    // Surface a rejected retry (e.g. "isn't in a failed state") instead of a silent reload.
    const res = await retryHostingProvision(id);
    if (res.error) {
      setError(res.error);
      return;
    }
    window.location.reload();
  }

  return (
    <div className="space-y-8">
      <div>
        <h1 className="text-xl font-semibold">Web Hosting</h1>
        <p className="mt-1 text-sm text-slate-400">
          Host your website without managing a server — we run PHP, databases, email and SSL for you. Start on a free
          subdomain or connect your own domain.
        </p>
      </div>

      {error && <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}

      {/* Your accounts — compact cards linking to the per-account dashboard. */}
      {accounts.length > 0 ? (
        <div className="space-y-4">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">Your hosting accounts</h2>
          <div className="grid gap-3 sm:grid-cols-2">
            {accounts.map((a) => (
              <AccountCard key={a.id} a={a} onRetry={() => retry(a.id)} />
            ))}
          </div>
        </div>
      ) : (
        <EmptyState
          title="No hosting accounts yet"
          sub="Pick a plan below and we’ll set up an isolated hosting account for you — on a free subdomain or your own domain."
        />
      )}

      {/* Order a (new) site — the checkout wizard. */}
      <div className="space-y-3">
        <h2 className="font-semibold">{accounts.length ? "Host another site" : "Host a new site"}</h2>
        {firstMonthFree && plans.length > 0 && (
          <div className="flex items-center gap-2 rounded-xl border border-emerald-500/25 bg-emerald-500/10 px-3 py-2 text-sm font-medium text-emerald-300">
            <span className="flex h-1.5 w-1.5 shrink-0 rounded-full bg-emerald-400 animate-pulse-dot" />
            Your first month is free on shared hosting — then the price you sign up at is the price you renew at.
          </div>
        )}
        <HostingDeployWizard
          plans={plans}
          apps={apps}
          annualDiscountPct={annualDiscountPct}
          firstMonthFree={firstMonthFree}
          balanceCents={balanceCents}
          hasCard={hasCard}
          cardLabel={cardLabel}
          stripeReady={stripeReady}
          tempSubdomainBase={tempSubdomainBase}
        />
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------- card --- */

function AccountCard({ a, onRetry }: { a: HostingAccountView; onRetry: () => void }) {
  const diskGB = Math.round(a.diskQuotaMB / 1024);
  const storage = a.diskUsedMB != null ? `${(a.diskUsedMB / 1024).toFixed(a.diskUsedMB < 1024 ? 2 : 1)} / ${diskGB} GB` : `${diskGB} GB`;

  const body = (
    <>
      <div className="flex items-start justify-between gap-2">
        <div className="min-w-0">
          <p className="truncate font-medium text-slate-100">{a.primaryDomain}</p>
          <p className="mt-0.5 text-xs text-slate-500">{a.planName} · PHP {a.phpVersion}</p>
        </div>
        <StatusDot status={a.status} />
      </div>
      <div className="mt-3 flex flex-wrap items-center gap-2 text-[11px] text-slate-400">
        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">Storage {storage}</span>
        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">{a.maxSites} extra site{a.maxSites === 1 ? "" : "s"}</span>
        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">{a.maxDatabases} DB{a.maxDatabases === 1 ? "" : "s"}</span>
        {a.sslActive && <Badge tone="green">HTTPS</Badge>}
      </div>
    </>
  );

  // A failed account can't be opened usefully — show the retry affordance inline.
  if (a.status === "FAILED") {
    return (
      <div className="card">
        {body}
        <div className="mt-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-300">
          Setup failed{a.error ? `: ${a.error}` : ""}.{" "}
          <button className="font-medium underline" onClick={onRetry}>Retry setup</button>
        </div>
      </div>
    );
  }

  return (
    <Link href={`/dashboard/hosting/${a.id}`} className="card card-hover block transition">
      {body}
      <p className="mt-3 text-xs font-medium text-brand-300">Manage →</p>
    </Link>
  );
}

import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { listHostingAccounts } from "@/lib/actions-hosting";
import { annualDiscountPct } from "@/lib/annual-discount";
import { firstMonthFreeAppliesTo, firstMonthFreeEnabled } from "@/lib/promo-redemption";
import { hostingAppCatalog } from "@/worker/hosting";
import { HOSTING_SUBDOMAIN_BASE } from "@/lib/hosting";
import { hasChargeableCard, cardDisplayLabel } from "@/lib/stripe-cards";
import { stripeConfigured } from "@/lib/stripe";
import { HostingClient } from "@/components/customer/HostingClient";

export const dynamic = "force-dynamic";

export default async function HostingPage() {
  const user = await requireUser();
  // The first-month-free promo is HOSTING-ONLY (firstMonthFreeAppliesTo) and only
  // when the owner toggle is on. Resolved server-side so the order UI advertises the
  // promo only when checkout will actually grant it — displayed === charged.
  const [plans, accounts, annualPct, promoOn] = await Promise.all([
    db.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    listHostingAccounts(),
    annualDiscountPct(),
    firstMonthFreeAppliesTo("HOSTING") ? firstMonthFreeEnabled() : Promise.resolve(false),
  ]);
  const planViews = plans.map((p) => ({
    id: p.id,
    name: p.name,
    priceCents: p.priceCents,
    diskGB: p.diskGB,
    maxSites: p.maxSites,
    maxDatabases: p.maxDatabases,
    bandwidthTB: p.bandwidthTB,
    mailboxes: p.mailboxes,
    freeMigration: p.freeMigration,
    featured: p.featured,
    tagline: p.tagline,
  }));
  const apps = hostingAppCatalog();
  const hasCard = hasChargeableCard(user);
  const cardLabel = hasCard
    ? cardDisplayLabel({ brand: user.cardBrand, last4: user.cardLast4, expMonth: user.cardExpMonth, expYear: user.cardExpYear })
    : null;
  return (
    <HostingClient
      plans={planViews}
      accounts={accounts}
      apps={apps}
      annualDiscountPct={annualPct}
      firstMonthFree={promoOn}
      balanceCents={user.balanceCents}
      hasCard={hasCard}
      cardLabel={cardLabel}
      stripeReady={stripeConfigured()}
      tempSubdomainBase={HOSTING_SUBDOMAIN_BASE}
    />
  );
}

